"""Build deterministic reports from an audited, completed saved-model packet."""
import argparse
import json
from pathlib import Path

p=argparse.ArgumentParser();p.add_argument('analysis',type=Path);p.add_argument('raw',type=Path);p.add_argument('output',type=Path)
a=p.parse_args();s=json.loads((a.analysis/'analysis.json').read_text(encoding='utf-8'))
assert s['status']=='completed' and s['verification_consistent'] and not s['failed_checks']
assert s['checks']==454 and s['latency_pairs']==440 and s['training_updates']==0
a.output.mkdir(parents=True,exist_ok=False)
families=['M0','P75','R','E','hybrid'];names={'M0':'M0 — плотная','P75':'Каналы 75%','R':'SVD / лучший R','E':'Лучший E','hybrid':'Каналы → SVD'}
quality={v['family']:v for v in s['quality']};timing={(v['family'],v['batch'],v['clock']):v for v in s['AB']}
f=lambda x,n=2:f'{x:.{n}f}'.replace('.',',')
packet='results/saved-model-evaluation-2026-10-26'
qt=[];st=[];storage=[];ids=[]
for k in families:
    q=quality[k];drop=(quality['M0']['test_top1']-q['test_top1'])*100
    qt.append(f"| {names[k]} | {f(q['validation_top1']*100)}% | {f(q['test_top1']*100)}% | {f(drop)} | {f(q['test_CE'],5)} | {f(q['fraction_M0']*100)}% |")
    storage.append(f"| {k} | {q['tensor_bytes']} | {q['TS_tensor_bytes']} | {q['TS_file_bytes']} |")
    ids.append(f"| {k} | `{q['checkpoint_sha256']}` | `{q['TS_sha256']}` |")
for batch in (1,128):
    for k in families[1:]:
        t=timing[k,batch,'cuda_event']
        st.append(f"| {names[k]} | {batch} | {f(t['median_M0_ms'],4)} | {f(t['median_model_ms'],4)} | {f(t['median_B_over_A'],4)} | {f(t['observed_A_over_B'],3)}× | {f(t['min_ratio'],4)}–{f(t['max_ratio'],4)} |")
ce={k:json.loads((a.raw/'quality'/f'{k}.json').read_text())['TS_equivalence']['CE_max_abs_difference'] for k in families}
md=f'''# Сохранённые ResNet18: качество, хранение и время одних и тех же TorchScript

26.10.2026 · [PR #140](https://github.com/v1docq/FedCore/pull/140) · [Интерактивный HTML](saved-model-evaluation-report.html) · [План](PLAN_SAVED_MODEL_EVALUATION.md)

**На пакете 128 все четыре компактные модели быстрее соответствующей M0.** Гибрид хранит 57,53% тензорных байтов контроля, даёт 93,58% против 94,11% на повторно использованном официальном тесте и наблюдаемое ускорение 1,305×. На пакете 1 R и E медленнее; у гибрида медиана парных отношений B/A равна 0,9716 (−2,84%), при этом есть выбросы. Это результат одного окна A100, а не доказательство устойчивого ускорения на любых нагрузках.

## Что именно сравнивается

Пять заранее закреплённых состояний из [матрицы восстановления](RECOVERY_BN_MATRIX.md): M0, каналы 75%, SVD / лучший R, лучший E и каналы → SVD. Все уже прошли 200 обновлений SGD при `lr=0.001`, без дополнительной BN. В этом пакете обучение, поиск и дополнительная калибровка не выполнялись. **Контроль M0 тоже восстановлен; это не исходная модель до SGD.** R совпадает с фиксированным SVD и не является шестым семейством. E — прежний выбранный результат короткого эволюционного поиска; новые графы не выбирались.

Каждый исходный снимок независимо загружен; его 5000 поисковых ответов и потерь точно повторили предыдущие NPZ. Затем модель экспортирована в TorchScript, сохранена, независимо загружена непосредственно на CUDA и проверена ещё на 5000 изображениях. До открытия тестовых меток зафиксированы все пять состояний и SHA-256. На официальном тесте и в измерениях времени использованы **одни и те же файлы TorchScript**.

Официальный тест CIFAR-10 уже использовался в предыдущих пакетах. Текущие результаты — описательная повторная оценка заранее выбранных весов; это не нетронутый окончательный тест. Публикуются все пять состояний. Выбор шага обучения в предыдущем пакете опирался на одну поисковую выборку, поэтому её точность не является независимой оценкой обобщения.

## Качество и хранение

Top-1 — доля правильных ответов. Поисковая выборка содержит 5000 изображений, официальный тест — 10 000. Потеря в процентных пунктах рассчитана к восстановленной M0 этого пакета. CE — средняя перекрёстная энтропия на официальном тесте. Байты включают физические тензорные хранилища параметров и буферов.

| Модель | Поисковая Top-1 | Тестовая Top-1 | Потеря к M0, п.п. | CE теста | Тензорные байты M0 |
| --- | ---: | ---: | ---: | ---: | ---: |
{chr(10).join(qt)}

R показывает наибольшую точность среди четырёх компактных точек, гибрид — наименьшее хранение. Разность R−E составляет 0,18 п.п., то есть 18 изображений этого теста. Одна M0 и одна пара поисков не устанавливают превосходство случайного поиска или эволюции. Старые критерии пилота не заменяются новым порогом и не переоцениваются задним числом.

Тензорный объём исходного снимка совпал с объёмом тензорных ZIP-хранилищ TorchScript. Размер всего файла включает также служебные данные и показывается отдельно:

| Модель | Тензоры исходного снимка, байт | Тензоры TorchScript, байт | Весь файл TorchScript, байт |
| --- | ---: | ---: | ---: |
{chr(10).join(storage)}

## Допуск времени и наблюдаемые эффекты

Все **семь A/A** прошли полный допуск: два пакета × два вида часов на сессию, всего 28 проверок. Использованы шесть предварительных A/A и заключительный M0 после четырёх A/B. Медианы A/A по 28 срезам лежат в пределах {f(min(v['median_ratio'] for v in s['AA']),4)}–{f(max(v['median_ratio'] for v in s['AA']),4)}. Окончательный допуск четырёх A/B подтверждён после заключительного контроля и успешного завершения.

Каждый срез содержит 20 пар с чередованием AB/BA; перед измерением — 20 вызовов прогрева, в блоке — 20 вызовов. Применён прежний A/A-допуск: медиана B/A 0,95–1,05, минимум 18/20 внутри 0,85–1,15, отношение медиан порядков 0,90–1,10. Допуск подтверждает пригодность окна по этому протоколу; он не является доверительным интервалом небольшого эффекта.

Ниже CUDA Events. M0 измерялась заново в каждой паре с кандидатом. Время — медианы мс на вызов; **B/A — медиана парных отношений, ускорение = 1 / median(B/A)**. Это не отношение двух отдельно рассчитанных медиан. Меньшее B/A означает меньшую задержку; ускорение меньше единицы означает замедление. Все пары сохранены без удаления выбросов.

| Модель B | Пакет | M0 A, мс | B, мс | Медиана B/A | Ускорение | Минимум–максимум B/A |
| --- | ---: | ---: | ---: | ---: | ---: | ---: |
{chr(10).join(st)}

При пакете 128 наблюдаются ускорения 1,116–1,305×; максимальное — у гибрида. При пакете 1 сокращение каналов даёт 1,097×, а медианы парных B/A для R и E равны 1,0650 и 1,0585. У гибрида медиана B/A 0,9716, но максимум достигает 1,3580; у R максимум — 1,4601, у E минимум — 0,7793. Малый эффект гибрида требует повторения в независимых окнах. Синхронизированное время даёт близкие медианы; переключение часов и все 20 пар доступны в HTML и [анализе]({packet}/analysis/analysis.json).

Это FP32, TorchScript, A100-PCIE-40GB, вход CIFAR-10 32×32, PyTorch 2.2.0+cu121 / CUDA 12.1 / cuDNN 8902, TF32 отключён. Загрузка модели, подготовка входа и перенос данных в измеряемые блоки не входят. Выводы не переносятся автоматически на весь обслуживающий конвейер, CPU, TensorRT, INT8, разреженные ядра или большие изображения.

## Проверки и расход бюджета

Исходные модели точно повторили все четыре массива предыдущих поисковых NPZ. У TorchScript идентификаторы, метки и классы совпали точно. Потери проверялись по **`|CE_TS − CE_eager| ≤ 1e-5 + 1e-5 × |CE_eager|`**; максимальные абсолютные расхождения по пяти моделям — {min(ce.values()):.8g}…{max(ce.values()):.8g}. Это комбинированный абсолютный и относительный допуск, а не обещание абсолютной ошибки ≤1e-5.

- Локальная CPU-серия: **292 passed / 20 skipped**, 79,80 с; пропущенные Linux-проверки выполнены на сервере.
- Установленный wheel на Linux с отключённой CUDA: **312 passed**, 41,94 с; предварительный допуск подтвердил 14 родительских файлов.
- Два CPU-примера внешнего ограничителя подтвердили завершение собственных потомков; независимая проверка не оставила блокирующих замечаний.
- [CI исходного коммита](https://github.com/v1docq/FedCore/actions/runs/40321039839): **6/6 заданий успешно**. Это проверка кода `0693a4b`, отдельно от публикации отчёта.
- Независимый пересчёт только по экспортированным массивам и журналам: **{s['checks']} согласованных проверок**. Включены хеши исходных CIFAR-файлов, роли данных, происхождение весов, параметры среды, численные допуски, окончательное разрешение всех A/B и внешний бюджет.

Одна разрешённая попытка, без повтора: **{f(s['evaluation_seconds'],3)} с / {f(s['evaluation_seconds']/60,2)} из 30 минут**. Внутренняя рабочая часть — 151,674 с; бюджет учитывает полный внешний расход. Прежний расход — {f(s['prior_seconds'],3)} с, итог — **{f(s['total_seconds'],3)} с / {f(s['total_seconds']/60,2)} из 240 минут**. Выполнены ровно 50 000 поисковых строк, 50 000 тестовых строк и 440 пар времени. Обновлений SGD — 0.

Пиковая CUDA-память процесса: выделено {f(s['peak_allocated_bytes']/2**30,3)} ГиБ, зарезервировано {f(s['peak_reserved_bytes']/2**30,3)} ГиБ; пик RSS — {f(s['peak_worker_rss_bytes']/2**30,3)} ГиБ. Это счётчики процесса, не полное потребление карты по nvidia-smi. Живой надзор не обнаружил чужих GPU-процессов или пропусков телеметрии; после завершения карта свободна. Подтверждена сохранность 14 использованных родительских файлов, 176 старых файлов результатов, четырёх прежних пакетов/сред и трёх исходных рабочих копий с 130 незавершёнными файлами.

## Воспроизводимость и ограничения

Код: `{s['source_commit']}`. SHA-256 wheel: `{s['wheel_sha256']}`. SHA-256 профиля: `{s['evaluation_protocol_sha256']}`. Новый режим CLI по умолчанию проверяет целостность без Torch/CUDA; исполнение включается явно. [Пакет свидетельств]({packet}/README.md) содержит исходные NPZ, все пары, управляющие журналы, среду, неизменённые входы анализа и сценарии пересчёта. Десять файлов весов (пять исходных и пять TorchScript) сохранены на A100; в Git опубликованы их удалённо проверенные SHA-256 и размеры. Сами веса локально не скачивались. Анализ без моделей воспроизводим, полное исполнение требует этих весов и данных.

| Модель | SHA-256 исходного снимка | SHA-256 сохранённого TorchScript |
| --- | --- | --- |
{chr(10).join(ids)}

Этот пакет связывает качество, хранение и время конкретных сохранённых артефактов. Он не проверяет устойчивость между независимо обученными M0, повторами поиска или отдельными временными окнами. Предыдущие неуспешные A/A, старые состояния весов и отрицательные результаты BN сохранены; причина старого сдвига загрузки не установлена. Issue #99 остаётся открытой.

Дальнейший содержательный этап — независимые исходные модели и поисковые повторы с равным бюджетом для R/E, заранее закреплённым восстановлением и отдельными окнами времени. Для расширения CV-профиля затем нужны более крупные изображения и архитектуры. Это предложение следующего протокола; новых вычислительных запусков этим отчётом не выполнялось и не назначалось.
'''
(a.output/'SAVED_MODEL_EVALUATION.md').write_text(md,encoding='utf-8')
pair_data=[]
for k in families[1:]:
    r=json.loads((a.raw/'latency'/f'M0_vs_{k}_AB.json').read_text())
    for batch,b in r['batches'].items():
        for pair in b['pairs']:
            for clock in ('cuda_event','synchronized_wall'):
                pair_data.append({'family':k,'batch':int(batch),'clock':clock,'pair':pair['pair']+1,'order':pair['order'],
                    'ratio':pair['B'][clock+'_seconds']/pair['A'][clock+'_seconds']})
data={'summary':s,'pairs':pair_data,'names':names,'families':families,'packet':packet,'CE_max':ce}
template=Path(__file__).with_name('saved-evaluation.template.html').read_text(encoding='utf-8')
(a.output/'saved-model-evaluation-report.html').write_text(template.replace('@@DATA@@',json.dumps(data,sort_keys=True,allow_nan=False).replace('</','<\\/')),encoding='utf-8')
print(json.dumps({'reports':2,'checks':s['checks'],'pairs_plotted':len(pair_data),'new_model_execution':False}))
